#!/usr/bin/env python3
"""Persistent HTTP key-value service.

A dependency-free Python 3.11+ HTTP service that stores JSON values keyed by
URL-encoded keys, supports per-entry TTLs, and persists live state to a JSON
file using atomic replacement so that state survives a restart and expired
entries never reappear.

Usage::

    python3 server.py --host 127.0.0.1 --port PORT --data PATH

When ``PORT`` is 0 a free port is chosen and the first stdout line is
``LISTENING <actual-port>`` (flushed immediately). Diagnostics go to stderr.
"""

from __future__ import annotations

import argparse
import json
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlparse

MAX_BODY = 1024 * 1024  # 1 MiB request-body limit


class Store:
    """Thread-safe, JSON-persistent key-value store with optional TTL."""

    def __init__(self, path: str):
        self.path = path
        self.lock = threading.RLock()
        self.data: dict[str, dict] = {}
        self._load()

    # ---- persistence -----------------------------------------------------
    def _load(self) -> None:
        if not self.path:
            return
        with self.lock:
            try:
                with open(self.path, "r", encoding="utf-8") as fh:
                    raw = json.load(fh)
            except FileNotFoundError:
                return
            except (OSError, ValueError):
                # Corrupt or unreadable state file: start empty.
                sys.stderr.write("kv: could not parse state file, starting empty\n")
                return
            if not isinstance(raw, dict):
                return
            now = time.time()
            for key, entry in raw.items():
                if not isinstance(key, str) or not isinstance(entry, dict):
                    continue
                if "value" not in entry:
                    continue
                exp = entry.get("expires_at")
                if exp is not None:
                    if not isinstance(exp, (int, float)) or isinstance(exp, bool):
                        continue
                    if exp <= now:
                        continue  # expired entries must not reappear
                self.data[key] = {"value": entry["value"], "expires_at": exp}

    def _save_locked(self) -> None:
        # Caller must hold self.lock.
        if not self.path:
            return
        now = time.time()
        out: dict[str, dict] = {}
        for key, entry in self.data.items():
            exp = entry["expires_at"]
            if exp is not None and exp <= now:
                continue  # do not persist expired entries
            out[key] = {"value": entry["value"], "expires_at": exp}
        directory = os.path.dirname(os.path.abspath(self.path))
        os.makedirs(directory, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=directory, suffix=".tmp", prefix=".kv-")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(out, fh, ensure_ascii=False)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, self.path)  # atomic replacement
        except Exception:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    # ---- helpers ---------------------------------------------------------
    @staticmethod
    def _is_expired(entry: dict, now: float) -> bool:
        exp = entry.get("expires_at")
        return exp is not None and exp <= now

    # ---- operations ------------------------------------------------------
    def put(self, key: str, value, ttl_seconds):
        with self.lock:
            now = time.time()
            existing = self.data.get(key)
            if existing is not None and self._is_expired(existing, now):
                existing = None
                del self.data[key]
            created = existing is None
            expires_at = None if ttl_seconds is None else now + ttl_seconds
            self.data[key] = {"value": value, "expires_at": expires_at}
            self._save_locked()
            return created

    def get(self, key: str):
        with self.lock:
            now = time.time()
            entry = self.data.get(key)
            if entry is None:
                return None, False
            if self._is_expired(entry, now):
                del self.data[key]
                self._save_locked()
                return None, False
            return entry["value"], True

    def delete(self, key: str) -> bool:
        with self.lock:
            now = time.time()
            entry = self.data.get(key)
            if entry is None:
                return False
            if self._is_expired(entry, now):
                del self.data[key]
                self._save_locked()
                return False
            del self.data[key]
            self._save_locked()
            return True

    def list_keys(self) -> list[str]:
        with self.lock:
            now = time.time()
            live: list[str] = []
            expired: list[str] = []
            for key, entry in self.data.items():
                if self._is_expired(entry, now):
                    expired.append(key)
                else:
                    live.append(key)
            if expired:
                for key in expired:
                    del self.data[key]
                self._save_locked()
            live.sort()
            return live


class KVHandler(BaseHTTPRequestHandler):
    server_version = "kv/1.0"
    store: Store = None  # type: ignore[assignment]

    # ---- logging to stderr ----------------------------------------------
    def log_message(self, fmt, *args):
        sys.stderr.write(
            "%s - %s\n" % (self.address_string(), fmt % args)
        )

    # ---- low-level helpers ----------------------------------------------
    def _send_json(self, status: int, payload) -> None:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            try:
                self.wfile.write(body)
            except (BrokenPipeError, ConnectionResetError):
                pass

    def _err(self, status: int, message: str) -> None:
        self._send_json(status, {"error": message})

    def _send_empty(self, status: int) -> None:
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _read_body(self):
        try:
            length = int(self.headers.get("Content-Length", "") or 0)
        except (TypeError, ValueError):
            return None, "invalid Content-Length", 400
        if length < 0:
            return None, "invalid Content-Length", 400
        if length > MAX_BODY:
            return None, "request body too large", 413
        try:
            body = self.rfile.read(length) if length else b""
        except OSError:
            return None, "could not read body", 400
        if len(body) > MAX_BODY:
            return None, "request body too large", 413
        return body, None, None

    # ---- routing --------------------------------------------------------
    def _route(self):
        path = urlparse(self.path).path
        parts = path.split("/")
        if parts and parts[0] == "":
            parts = parts[1:]
        if not parts:
            return (None, None)
        first = parts[0]
        if first == "health" and len(parts) == 1:
            return ("health", None)
        if first == "v1":
            if len(parts) == 2 and parts[1] == "keys":
                return ("keys", None)
            if len(parts) >= 2 and parts[1] == "kv":
                raw = "/".join(parts[2:])
                return ("kv", raw)
        return (None, None)

    # ---- method dispatch ------------------------------------------------
    def do_GET(self):
        self._dispatch("GET")

    def do_PUT(self):
        self._dispatch("PUT")

    def do_DELETE(self):
        self._dispatch("DELETE")

    def do_POST(self):
        self._dispatch("POST")

    def do_PATCH(self):
        self._dispatch("PATCH")

    def do_HEAD(self):
        self._dispatch("HEAD")

    def do_OPTIONS(self):
        self._dispatch("OPTIONS")

    def send_error(self, code, message=None, explain=None):
        # Override the default HTML error page with a JSON response so that
        # every error path (including malformed request lines handled by the
        # base class) returns JSON.
        try:
            self._send_json(code, {"error": message or self.responses.get(code, ("error",))[0]})
        except Exception:
            pass

    def _dispatch(self, method: str) -> None:
        route, raw_key = self._route()
        if route is None:
            self._err(404, "unknown route")
            return
        if route == "health":
            if method == "GET":
                self._send_json(200, {"status": "ok"})
            else:
                self._err(405, "method not allowed")
            return
        if route == "keys":
            if method == "GET":
                self._send_json(200, {"keys": self.store.list_keys()})
            else:
                self._err(405, "method not allowed")
            return
        if route == "kv":
            self._handle_kv(method, raw_key)
            return
        self._err(404, "unknown route")

    # ---- kv handlers ----------------------------------------------------
    def _handle_kv(self, method: str, raw_key: str) -> None:
        if raw_key == "":
            self._err(400, "empty key")
            return
        try:
            key = unquote(raw_key, encoding="utf-8", errors="strict")
        except ValueError:
            self._err(400, "invalid key encoding")
            return
        if "/" in key:
            self._err(400, "key must not contain '/'")
            return
        if not key:
            self._err(400, "empty key")
            return
        if method == "PUT":
            self._kv_put(key)
        elif method == "GET":
            self._kv_get(key)
        elif method == "DELETE":
            self._kv_delete(key)
        else:
            self._err(405, "method not allowed")

    def _kv_put(self, key: str) -> None:
        body, err, status = self._read_body()
        if err is not None:
            self._err(status, err)
            return
        if not body:
            self._err(400, "empty body")
            return
        try:
            payload = json.loads(body.decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            self._err(400, "malformed JSON")
            return
        if not isinstance(payload, dict):
            self._err(400, "body must be a JSON object")
            return
        if "value" not in payload:
            self._err(400, "missing 'value'")
            return
        value = payload["value"]
        ttl = payload.get("ttl_seconds")
        if ttl is not None:
            if isinstance(ttl, bool) or not isinstance(ttl, (int, float)):
                self._err(400, "invalid ttl_seconds")
                return
            if ttl <= 0 or ttl == float("inf") or ttl != ttl:  # <=0, inf, NaN
                self._err(400, "ttl_seconds must be finite and greater than zero")
                return
        created = self.store.put(key, value, ttl)
        self._send_json(201 if created else 200, {"key": key, "value": value})

    def _kv_get(self, key: str) -> None:
        value, found = self.store.get(key)
        if not found:
            self._err(404, "not found")
            return
        self._send_json(200, {"key": key, "value": value})

    def _kv_delete(self, key: str) -> None:
        if self.store.delete(key):
            self._send_empty(204)
        else:
            self._err(404, "not found")


def parse_args(argv=None):
    parser = argparse.ArgumentParser(
        description="Persistent HTTP key-value service."
    )
    parser.add_argument("--host", default="127.0.0.1", help="bind host")
    parser.add_argument("--port", type=int, default=0, help="bind port (0 = free)")
    parser.add_argument("--data", required=True, help="path to JSON state file")
    return parser.parse_args(argv)


def main(argv=None) -> int:
    args = parse_args(argv)
    store = Store(args.data)

    server = ThreadingHTTPServer((args.host, args.port), KVHandler)
    server.daemon_threads = True
    KVHandler.store = store

    def request_shutdown(*_):
        # Called in the main thread; unblocks serve_forever running in worker.
        try:
            server.shutdown()
        except Exception:
            pass

    signal.signal(signal.SIGTERM, request_shutdown)
    signal.signal(signal.SIGINT, request_shutdown)

    actual_port = server.server_address[1]
    print("LISTENING %d" % actual_port, flush=True)
    sys.stderr.write("kv: listening on %s:%d (data=%s)\n" % (args.host, actual_port, args.data))

    worker = threading.Thread(target=server.serve_forever, daemon=True)
    worker.start()
    try:
        worker.join()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

